  VALUES 
    (453::BIGINT, 'Muy buena opción, el curso no es pesado y se aprende mucho. Siga las instrucciones y no va a tener ningún problema.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Respetado por los estudiantes']::TEXT[], '2026-07-07T00:00:00+00:00'::TIMESTAMPTZ, '0276d345bbf4477004bb5edbfdc75b3c69f3bc445ea2dac1eb69d39c3e11a39b'::TEXT, ARRAY[1778]::BIGINT[]),
    (453::BIGINT, 'Ir a consulta es importante, pedirle ayuda en el proyecto es lo que de verdad permite entender a más profundidad el curso y lo que uno debe hacer como profesional'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'La participación importa']::TEXT[], '2026-07-02T00:00:00+00:00'::TIMESTAMPTZ, 'ab4fd2187fd5066331e4057a1449e8fb6752a97a55528ccfd81918310e6b9f21'::TEXT, ARRAY[1757]::BIGINT[]),
    (453::BIGINT, 'Una palabra; vocación.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Clases excelentes']::TEXT[], '2026-06-29T00:00:00+00:00'::TIMESTAMPTZ, '6e249f335fa21ed30fe9161eda720b89217561c6d567d22b508586a47905ff27'::TEXT, ARRAY[1778]::BIGINT[]),
    (453::BIGINT, 'Muy buen profesor, enseña súper claro y es muy amable. Siga las instrucciones que él da y le va a ir bien. En realidad es un profe que lo motiva a uno a hacer las cosas bien y le enseña no solo para el curso sino para la vida. Excelente opción.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Respetado por los estudiantes']::TEXT[], '2025-12-03T00:00:00+00:00'::TIMESTAMPTZ, '1ee5b90be29e00d7d72fdc5479a2ebadfaa635ea87ed3bdd4b796d5a5e03cf22'::TEXT, ARRAY[1757]::BIGINT[]),
    (453::BIGINT, 'Es un muy buen profesor, si usted realmente quiere aprender, matricule con él.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria', 'Da crédito extra']::TEXT[], '2025-07-21T00:00:00+00:00'::TIMESTAMPTZ, '917ea4cd88cc0f59e6c118dd373a0ed0e77d52833410d743f93c7496a4a13089'::TEXT, ARRAY[1779]::BIGINT[]),
    (453::BIGINT, 'Es buen profesor, si quieren aprender. Hace entretenidas las clases y de vez en cuando da credito extra en quices. Suerte.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Respetado por los estudiantes']::TEXT[], '2025-07-06T00:00:00+00:00'::TIMESTAMPTZ, '98ef384d81a4ef4261eb8a42d7789666e18ad59ae3ddd47ab581770e989a47a2'::TEXT, ARRAY[1757]::BIGINT[]),
    (453::BIGINT, 'El profe dio por primera vez el curso. Lo hizo muy bien, la clase fue dinámica y sustancial. Lo recomiendo'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-06-11T00:00:00+00:00'::TIMESTAMPTZ, 'd763f1b4b0dd69775447020b187017d134329ecbc775a2f3fa0daf6e9a0443df'::TEXT, ARRAY[1797]::BIGINT[]),
    (453::BIGINT, 'Dele sin miedo, es estricto pero muy bueno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Clases excelentes']::TEXT[], '2023-11-28T00:00:00+00:00'::TIMESTAMPTZ, '33fc1889ad2d96747a3384439ab940a0ddae7b4613192926e1f2a82fc39f024d'::TEXT, ARRAY[1779]::BIGINT[]),
    (453::BIGINT, 'Hubiera matriculado con el las probas de haber sabido lo bueno que es, explica demasiado bien la materia y uno logra pasar el 100% de la clase concentrado, lo recomiendo'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Aspectos de calificación claros']::TEXT[], '2023-11-14T00:00:00+00:00'::TIMESTAMPTZ, 'e9358d41659b24c32152cb95c979b415a1042aaeff825b933d76d90d0ffe4326'::TEXT, ARRAY[1779]::BIGINT[]),
    (453::BIGINT, 'De los mejores profes de la Escuela de Produ, explica súper bien, pero es muy extricto. El curso demanda de mucho tiempo y práctica, pero se aprende bastante. Califica rudo.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-11-07T00:00:00+00:00'::TIMESTAMPTZ, 'e8438bcc1bb9c42d46b73e2a6507c8d4e2288cf38e43e175cba49a95e70237a0'::TEXT, ARRAY[1779]::BIGINT[]),
    (453::BIGINT, 'El profe es bastante bueno explicando. Hay que estudiar mucho'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-11-01T00:00:00+00:00'::TIMESTAMPTZ, '6a5e6062bb237cdebbe4874765a0adc4f3ab18da8b8e4a517130a6ed43145d42'::TEXT, ARRAY[1779]::BIGINT[]),
    (453::BIGINT, 'El profesor es bastante bueno, pero tiene su humor. Sigue las instrucciones al pie de la letra y no da brazo a torcer. Califica duro los quices y exámenes teóricos, donde una sola palabra mal empleada ya es suficiente para quitarle los puntos.'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2023-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'c0eb41506b05cfc69e26128b2203e65ca35753fec59ab60725c9039a060b617c'::TEXT, ARRAY[1779]::BIGINT[]),
    (453::BIGINT, 'Si usted tiene la posibilidad de matricular Proba con él, hágalo de una, es un profe excelente, explica claro y las evaluaciones no son difíciles. Eso sí, sea puntual y honesto con él.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2023-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'd5e649273fa4384052694c24b352984c04d960daeaad61631089dd02c355e4cd'::TEXT, ARRAY[1728]::BIGINT[]),
    (453::BIGINT, 'Se tira pedos'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo']::TEXT[], '2023-02-08T00:00:00+00:00'::TIMESTAMPTZ, '9c0246a03fb6a915a2e3c4e3987a202f03abed5d385da8d8526bf674053fb121'::TEXT, ARRAY[1778]::BIGINT[]),
    (453::BIGINT, 'Es probablemente uno de los tres verdaderamente buenos profes en la escuela de Produ. Ma mayoría suelen convertir a los estudiantes en Usuarios de Minitab, él no, él ensaña. El mejor, es sarcástico a veces, pero sólo para darle sazón a la clase. 100% el mejor'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Tomaría su clase nuevamente']::TEXT[], '2022-12-07T00:00:00+00:00'::TIMESTAMPTZ, '6b1d544e87fb6bf3405cc91336ea40dc4ed6ff82535c4049b87da3990236327e'::TEXT, ARRAY[1728, 1742]::BIGINT[]),
    (453::BIGINT, 'Demasiado chistoso, nada que decir, todas las clases son didácticas a nivel pedagógico y personal.DOE con este profe es lo mejor que se le puede ocurrir matricular, aunque sea a las 7 a.m.El curso no es difícil, solo es hacer las evaluaciones y prestar atención.No se asuste cuando lo vea a los ojos.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-12-03T00:00:00+00:00'::TIMESTAMPTZ, 'deddff6b7d8778e989f5655c990a69cdfa3537ece49e7a10100b074158132661'::TEXT, ARRAY[1779]::BIGINT[]),
    (453::BIGINT, 'Es un buen profe, pero tiene un carácter un poco dificil, puede ser sarcástico o burlista. Hay que participar MUCHO si quiere que la clase buena. Tiene preferencias hacia la gente que participa. Da consejos del trabajo en la calle, sus evaluaciones son justas y su retroalimentación es buena.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Respetado por los estudiantes']::TEXT[], '2021-12-02T00:00:00+00:00'::TIMESTAMPTZ, 'd0309484360d97502191d807efdf3d461a6593b2d8fb6520dbf72727b35cc2ea'::TEXT, ARRAY[1757]::BIGINT[]),
    (453::BIGINT, 'Excelente profesor, siempre busca el crecimiento del estudiante tanto académico como personal. De los profes que vale la pena llevar todos los cursos que se puedan'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2021-01-31T00:00:00+00:00'::TIMESTAMPTZ, 'd3593a8eb0e23dc1834d4b8c75bafc7c79aebf581908c84503c84e1b1fc717e5'::TEXT, ARRAY[1757, 1728]::BIGINT[]),
    (453::BIGINT, 'Excelente profesor, hay que participar bastante, los exámenes y quices son accesibles (si se estudia obvio). Explica muy claro, y por lo general si no entiende le pide a algún integrante del grupo que explique para ver si la materia queda clara.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-16T00:00:00+00:00'::TIMESTAMPTZ, '833d6c0af0ecf5cdd9051f2debfab2d2c6c5875ab3021de47c1c1c6c4ed6986d'::TEXT, ARRAY[1778]::BIGINT[]),
    (453::BIGINT, 'Volvería a tomar su clase de nuevo la verdad, es un exelente profesor, trata de explicar lo mejor que pueda, si no sabe algo le va a decir que no sabe, eso sí aveces se enreda, pero trata de que uno entienda, lo llevé en modalidad virtual y recomiendo llevarlo con él.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Inspirador']::TEXT[], '2020-08-09T00:00:00+00:00'::TIMESTAMPTZ, 'e77a12d2a3950306c7871aa8d772eaad657a8e34f34ab797ee46c931d73fae60'::TEXT, ARRAY[1778]::BIGINT[]),
    (453::BIGINT, 'Excelentes clases. Excelente profesor. Volvería a llevar el curso con él.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2019-10-18T00:00:00+00:00'::TIMESTAMPTZ, 'c40cf9a498ec1f661076f6437f71d49649ec0d429e5affd44c734c03d635aa1e'::TEXT, ARRAY[1778]::BIGINT[]),
    (453::BIGINT, 'Da muchos consejos de proyecto de graduación y de trabajo en la calle. No explica muy claro. Puntualidad es MUY importante. Es irrespetuoso con los estudiantes (bromista, sarcástico, inapropiado). Los quices y exámenes son rudos.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Exámenes retadores']::TEXT[], '2019-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'f5be155acb610fbbd5245f7cd6f63baad18029d5608412e44113723c40c400c5'::TEXT, ARRAY[1743]::BIGINT[]),
    (453::BIGINT, 'Buen profesor, explica de manera muy clara, ponga atencion, participe y practique con los libros que recomienda y pasa facil. No espere nada regalado'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Tomaría su clase nuevamente']::TEXT[], '2019-01-29T00:00:00+00:00'::TIMESTAMPTZ, '5ee601499c22e0c56b60147134790830d84c0102ca13ebb1df99ab907d14a6e5'::TEXT, ARRAY[1728]::BIGINT[]),
    (453::BIGINT, 'La verdad no me gustó como se dirige a la clase... La materia es muy fácil pero no es como llevar mate o física, hay que interpretar bien lo que pregunta y califica bueno o malo (califica mal, por un pequeño error me fue mal en un examen porque valía 20 pts esa parte).'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-30T00:00:00+00:00'::TIMESTAMPTZ, 'd246dad4f5198b6b47263b3e76b5d316719f9cbda80ba9c24d8ded7cdbfcc362'::TEXT, ARRAY[1728]::BIGINT[]),
    (453::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-26T00:00:00+00:00'::TIMESTAMPTZ, '1c0d1798d2c01940db951f69ea79fe5ffda3c6d53bbe78556cb8d06e54743c87'::TEXT, ARRAY[1728]::BIGINT[]),
    (453::BIGINT, 'Es un curso para el que hay que estudiar. El profe intenta motivar para que la gente vaga se esfuerce. Si son unos vagos y chancletas, van a mamar. Si le ponen, pasan bien. Es chistoso en clase. El segundo examen es en compu, aprendan a usar minitab bien (no me eximí porque me vacunó en el 2do).'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Exámenes retadores']::TEXT[], '2018-11-07T00:00:00+00:00'::TIMESTAMPTZ, '1c85a299a56873e7fe85513add1303b13bb9b9f3a91250d7ec877d274c61e154'::TEXT, ARRAY[1743]::BIGINT[]),
    (453::BIGINT, 'Me parece buen profesor, si no entiendo el porque invierte tiempo mal hablando de otros profesores'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo']::TEXT[], '2018-07-30T00:00:00+00:00'::TIMESTAMPTZ, '9d44fc931a207a7769e20cd08c1ad344f9707020edacd763a52a8aff4407e7d7'::TEXT, ARRAY[1191, 1274, 1272, 4836, 963]::BIGINT[]),
    (453::BIGINT, 'No es malo pero deberia dejar de hablar mal de otros profesores como Jary Brenes.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa']::TEXT[], '2018-06-27T00:00:00+00:00'::TIMESTAMPTZ, '5f90a8db672445595fe1c215149c5d0f6a581155ac65882441688cda1260e723'::TEXT, ARRAY[1191, 1274, 1272, 4836, 963]::BIGINT[]),
    (453::BIGINT, 'Le encanta que se le quede la gente, especialmente si usted no habla en clase o es una persona tímida. Los exámenes son sin sentido, le gusta que usted se aprenda cada cosa del libro aunque sepa todo la parte del análisis y la práctica y tiene sus argollas.'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'La participación importa']::TEXT[], '2018-06-25T00:00:00+00:00'::TIMESTAMPTZ, '0039dbd1afe841e9176afa8da5ee47c81065c726d9d247d075caee89559fce9a'::TEXT, ARRAY[2851, 3614]::BIGINT[]),
    (453::BIGINT, 'Sin duda el mejor, no lo piense para matricular con él, es súper divertido, se aprende un montón y califica a como explica. El mejor para cualquier proba :)'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-23T00:00:00+00:00'::TIMESTAMPTZ, '13714110a9bd0f9424bc6d19c6d1a0b2c31268e53d260354204493c359ae9239'::TEXT, ARRAY[1191, 1274, 1272, 4836, 963]::BIGINT[]),
    (453::BIGINT, 'Tiene su grupo de estudiantes favoritos si no le caes bien acorde a sus parámetros te agarra entre ojos!'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-21T00:00:00+00:00'::TIMESTAMPTZ, '11f80a3e7e29d3ba8fe4033a90837f0c6642b361315a784cc748a2087a0961c1'::TEXT, ARRAY[2851, 3614]::BIGINT[]),
    (453::BIGINT, 'Este profe esta solo. Demasiado recomendado, de los profe que da proba es el mejor. Explica super bien, los exámenes si son un poco rudos porque en algunos solo pide la respuesta y no evalúa procedimiento, pero califica justo. Con el se pasa y se aprende.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-18T00:00:00+00:00'::TIMESTAMPTZ, 'ebf2be1ca90fd73f6c6545e4e0c3ef3254a018cfb6075efe47f88289bb1d2219'::TEXT, ARRAY[1742, 963]::BIGINT[]),
    (453::BIGINT, 'Excelente persona y profesor. Explica muy claro y califica justo. Las clases son divertidas y ayuda mucho al estudiante si uno muestra interés. Recomendado'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2018-06-16T00:00:00+00:00'::TIMESTAMPTZ, '438899790799e3e59e3e40c8fe04aa0621f4d19bf641764d7761b2b6496ddd73'::TEXT, ARRAY[1743]::BIGINT[]),
    (453::BIGINT, 'Es un profesor malo. Uno aprende poco con el y lo peor de todo es lo burlista que es. Dudo que sepa realmente de que habla.'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-05-05T00:00:00+00:00'::TIMESTAMPTZ, 'ee17c4cf541983f99d7892e983b2320ef7652949271d806812c28bfa922fa674'::TEXT, ARRAY[1779]::BIGINT[]),
    (453::BIGINT, 'Él no da clases normales, este mae forma ingenieros de verdad, enseña para la vida. Es muy cómico y directo. No es fácil de llevar, hay que agarrarle el toque, pero vale la pena.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Exámenes retadores', 'Tomaría su clase nuevamente']::TEXT[], '2018-02-14T00:00:00+00:00'::TIMESTAMPTZ, '1399ed0e45e335f6b990c99c4fbec70d314b0463f51ef5c32421380942e212a5'::TEXT, ARRAY[1728]::BIGINT[]),
    (453::BIGINT, 'De los mejores profesores de la escuela, ninguna clase va a ser fácil con el, pero explica de una forma única. siempre lo recomiendo de los mejores que hay para aprender sobre producción industrial.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-02-04T00:00:00+00:00'::TIMESTAMPTZ, '5b094be8afdea2e4283e3bc2dbc9bab9c03d152bb9c0f1582c30c394889eaabd'::TEXT, ARRAY[1756]::BIGINT[]),
    (453::BIGINT, 'La clase es muy entretenida, califica duro, muy buen profe, se aprende bastante'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-12-04T00:00:00+00:00'::TIMESTAMPTZ, '3b89bd0c98095f4c4739880b6727419a16e29b86c36c63c14901bc46e3a0bf9e'::TEXT, ARRAY[1758]::BIGINT[]),
    (453::BIGINT, 'Explica excelente y aclara todas las dudas hasta asegurarse de que todos entienden. A veces se pasa de confianzudo pero nada que no se pueda soportar. Examenes complicadillos, muchas tareas, es objetivo calificando y le ayuda a quien muestra interés'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'bb3943d18e8712d0ce07f5b7f81306ac202bad6fdd69246e0bc08f9dfde266b1'::TEXT, ARRAY[1743]::BIGINT[]),
    (453::BIGINT, 'El profe es excelente explicando, sus examenes no son sencillos, usualmente se saca cosas muy rebuscadas para la parte teórica. Los quices y tareas son accesibles y si se estudia y se da su tiempo se pasa, no regala NADA y es muy justo, muy parejo y sin preferencias'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Clases excelentes']::TEXT[], '2017-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'af505663bea5a85cbfc3e3bb6c785a26caf04f702d87f6511e5df54983137372'::TEXT, ARRAY[1743]::BIGINT[]),
    (453::BIGINT, 'Muy buen profesor; sin embargo, es muy exigente y deja trabajos pesados. El curso en sí es bastante aburrido, pero él siempre hace todo lo posible para que sean entretenidas las clases. En lo personal, se lo recomiendo, si realmente le pone bastante.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-05-28T00:00:00+00:00'::TIMESTAMPTZ, '011bcf0f9f27929eb4f5ba46ea143898c8411ef8ba28780bf3da0de14c08b074'::TEXT, ARRAY[1758]::BIGINT[]),
    (453::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Clases excelentes']::TEXT[], '2017-03-26T00:00:00+00:00'::TIMESTAMPTZ, '8ecb761fe6f3760b07fd3c39afadea0075bb8b4a882ab6aa2cf27a57bc355f05'::TEXT, ARRAY[1728]::BIGINT[]),
    (453::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa']::TEXT[], '2017-02-03T00:00:00+00:00'::TIMESTAMPTZ, 'b4f7962fa97cafc4e600a4193dad4e3c6a8768ef5c4b151fc2ff3ea230d4c89d'::TEXT, ARRAY[1728]::BIGINT[]),
    (453::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2017-02-03T00:00:00+00:00'::TIMESTAMPTZ, 'ca2a02db3ad0b5f5f462650dd5fe5d262e11dcc044c46c7e2dc78e20337f4edc'::TEXT, ARRAY[1757]::BIGINT[]),
    (453::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Brinda apoyo']::TEXT[], '2016-06-07T00:00:00+00:00'::TIMESTAMPTZ, 'a3b77ed3b05723a83da5d5161280fdb277a0a4a8c1499f88a6b8dac75f057edb'::TEXT, ARRAY[1728]::BIGINT[]),
    (453::BIGINT, 'Excelente profesor!'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-02-01T00:00:00+00:00'::TIMESTAMPTZ, 'dcd08bfd3979b5b2e1bb4f8942f83b9ffed7e3621a8e8d94016e9230278c4ae2'::TEXT, ARRAY[1728]::BIGINT[]),
    (453::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-29T00:00:00+00:00'::TIMESTAMPTZ, '7ede02c402abcd6a3a8b5b032caf6bdc055954ca295ca738f6ee3de089c6a4a8'::TEXT, ARRAY[1728]::BIGINT[]),
    (453::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('35','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-26T00:00:00+00:00'::TIMESTAMPTZ, '68699fef316ff776e84537e2425beef29033dd788d1a0c2a193dd33753776db6'::TEXT, ARRAY[2851, 3614]::BIGINT[]),
    (453::BIGINT, 'Realmente crea ingenieros, la personalidad es un poco dificil, pero es muy humano a la vez, si se estudia se pasa bien, pues explica muy claro y las veces nesesarias. Muy recomendado.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-14T00:00:00+00:00'::TIMESTAMPTZ, '410a64dd198b861ba5d94557ace30200868efe3a830edcff9e4926f528501cdd'::TEXT, ARRAY[1728, 1756]::BIGINT[]),
    (453::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-30T00:00:00+00:00'::TIMESTAMPTZ, 'b107fb706e3cc80bbbb9d7780c3b08a2c5b4087333f6ee8690424f98b14b108e'::TEXT, ARRAY[2851, 3614]::BIGINT[]),
    (453::BIGINT, 'Una persona difícil de soportar y trata de perjudicar'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-05T00:00:00+00:00'::TIMESTAMPTZ, 'd096ccb3ec56bc456bbc79174d6a516a69e1251b2484370adee70920655b5345'::TEXT, ARRAY[2851, 3614]::BIGINT[]),
    (453::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-08T00:00:00+00:00'::TIMESTAMPTZ, 'e0e373a11f543c1ef388304450c8878e1629dcba29531df91000855331c9fd6c'::TEXT, ARRAY[1728]::BIGINT[]),
    (453::BIGINT, 'Exámenes muy fáciles, es muy buena gente, muy "humano". Da puntos extra por todo.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-12-02T00:00:00+00:00'::TIMESTAMPTZ, '7cf860fdd5eb62097da2f419d1fd15baf2ddc4c8e42f2fe35b7df81e56ead786'::TEXT, ARRAY[1728]::BIGINT[]),
    (453::BIGINT, 'Da puntos extra. De los exámenes; se puede esperar lo que sea: tanto ejercicios muy fáciles, como muy rudos. Pero buen profe, y buena persona.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-12-01T00:00:00+00:00'::TIMESTAMPTZ, '91f8b9bd6872015cc96f4e66364272d992e2beb9387da817c70d5697fba23560'::TEXT, ARRAY[1728]::BIGINT[]),
    (453::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-12-01T00:00:00+00:00'::TIMESTAMPTZ, '9049b1ab09d10f9da53645e99d10d7bde105b35c7a70a2b1b7b8eb6c36111589'::TEXT, ARRAY[1728]::BIGINT[]),
    (453::BIGINT, 'Los cursos son pasables y se aprende para la vida.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-22T00:00:00+00:00'::TIMESTAMPTZ, '76c244f2101867358530653aa25d99e486a2f4d661839f8a3da8a18796e3cf17'::TEXT, ARRAY[1752]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
